import type { ComponentProps } from "@types";
import type { CSSObject } from "@emotion/react";
import type { ReactNode, Dispatch, SetStateAction } from "react";

export const SECTION_DEFAULT_OPEN = {
  FIRST: "first",
  ALL: "all",
  DETERMINED: "determined",
  NONE: "none",
} as const;

export interface AccordionSectionProps extends Omit<ComponentProps, "title"> {
  children: ReactNode;
  isExpanded?: boolean;
  isInitialOpen?: boolean;
  onValueChange?: (value: boolean) => void;
}

export type HeadingLevel = 1 | 2 | 3 | 4 | 5 | 6;

export type AccordionHeaderProps = ComponentProps &
  React.ButtonHTMLAttributes<HTMLButtonElement> & {
    as?: React.ElementType;
    children: ReactNode;
    headingLevel?: HeadingLevel;
  };

export interface AccordionContentProps extends ComponentProps {
  children: ReactNode;
  indent?: React.CSSProperties["paddingInlineStart"];
}

export interface AccordionIndicatorProps extends ComponentProps {
  icon?: ReactNode;
  collapseIcon?: ReactNode;
  isLeading?: boolean;
}

export interface AccordionTitleProps extends ComponentProps {
  children: ReactNode;
}

export type SectionsInitiallyOpen =
  (typeof SECTION_DEFAULT_OPEN)[keyof typeof SECTION_DEFAULT_OPEN];

export type AccordionSize = "default" | "sm";

// Props for the accordion (root) component
export type AccordionProps = ComponentProps & {
  onePanelAtATime?: boolean;
  sectionsInitiallyOpen?: SectionsInitiallyOpen;
  size?: AccordionSize;
  styleSlots?: {
    root?: CSSObject;
    small?: CSSObject;
    section?: CSSObject;
    sectionExpanded?: CSSObject;
    header?: CSSObject;
    button?: CSSObject;
    buttonExpanded?: CSSObject;
    buttonFocus?: CSSObject;
    contentContainer?: CSSObject;
    contentContainerExpanded?: CSSObject;
    contentInner?: CSSObject;
    indicator?: CSSObject;
    indicatorExpanded?: CSSObject;
    indicatorLeading?: CSSObject;
    indicatorLeadingExpanded?: CSSObject;
    title?: CSSObject;
  };
};

export interface AccordionContextType {
  openIndex: number[] | null;
  setOpenIndex: Dispatch<SetStateAction<number[] | null>>;
  onePanelAtATime: boolean;
  registerSection: (isInitialOpen: boolean) => number;
  sectionsInitiallyOpen?: SectionsInitiallyOpen;
}
